#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>
#include <string>
#include "lodepng.h"
#include "cJSON.h"

static char* read_file(const char* path, size_t* len){
    FILE* f=fopen(path,"rb");
    if(!f){fprintf(stderr,"cannot open %s\n",path);exit(1);}
    fseek(f,0,SEEK_END); long n=ftell(f); fseek(f,0,SEEK_SET);
    char* buf=(char*)malloc(n+1);
    if(fread(buf,1,n,f)!=(size_t)n){fprintf(stderr,"read error\n");exit(1);}
    buf[n]='\0'; fclose(f); if(len)*len=n; return buf;
}

// Flatten a cJSON array (possibly nested) of numbers into a vector, row-major.
static void flatten(cJSON* node, std::vector<double>& out){
    if(cJSON_IsArray(node)){
        cJSON* c=NULL;
        cJSON_ArrayForEach(c,node) flatten(c,out);
    } else if(cJSON_IsNumber(node)){
        out.push_back(node->valuedouble);
    }
}

static std::vector<double> get_tensor(cJSON* root,const char* key){
    cJSON* n=cJSON_GetObjectItemCaseSensitive(root,key);
    if(!n){fprintf(stderr,"missing key %s\n",key);exit(1);}
    std::vector<double> v; flatten(n,v); return v;
}

// out[o] = sum_i W[o*in+i]*x[i] + b[o], optional ReLU
static std::vector<double> linear(const std::vector<double>& x,
                                  const std::vector<double>& W,
                                  const std::vector<double>& b,
                                  int in,int out,bool relu){
    std::vector<double> y(out);
    for(int o=0;o<out;o++){
        double s=b[o];
        const double* wr=&W[(size_t)o*in];
        for(int i=0;i<in;i++) s+=wr[i]*x[i];
        if(relu && s<0) s=0;
        y[o]=s;
    }
    return y;
}

int main(int argc,char** argv){
    if(argc<3){fprintf(stderr,"usage: %s weights.json image.png\n",argv[0]);return 1;}
    const char* wpath=argv[1];
    const char* ipath=argv[2];

    // Load weights
    size_t wlen; char* wtxt=read_file(wpath,&wlen);
    cJSON* root=cJSON_Parse(wtxt);
    if(!root){fprintf(stderr,"json parse error\n");return 1;}
    std::vector<double> iw=get_tensor(root,"input_layer.weight");
    std::vector<double> ib=get_tensor(root,"input_layer.bias");
    std::vector<double> hw=get_tensor(root,"hidden_layer.weight");
    std::vector<double> hb=get_tensor(root,"hidden_layer.bias");
    std::vector<double> ow=get_tensor(root,"output_layer.weight");
    std::vector<double> ob=get_tensor(root,"output_layer.bias");

    int in_dim=784;
    int hid=(int)ib.size();
    int nclass=(int)ob.size();

    // Load image as 8-bit grayscale
    std::vector<unsigned char> img;
    unsigned w,h;
    unsigned err=lodepng::decode(img,w,h,ipath,LCT_GREY,8);
    if(err){fprintf(stderr,"png decode error %u: %s\n",err,lodepng_error_text(err));return 1;}

    // Preprocess: resize expectation 28x28, normalize (x/255-0.1307)/0.3081
    std::vector<double> x(in_dim);
    const double mean=0.1307, std=0.3081;
    for(int p=0;p<in_dim;p++){
        double v = (p < (int)(w*h)) ? (double)img[p] : 0.0;
        x[p]=((v/255.0)-mean)/std;
    }

    std::vector<double> a=linear(x,iw,ib,in_dim,hid,true);
    std::vector<double> b2=linear(a,hw,hb,hid,hid,true);
    std::vector<double> logits=linear(b2,ow,ob,hid,nclass,false);

    int best=0; double bv=logits[0];
    for(int i=1;i<nclass;i++) if(logits[i]>bv){bv=logits[i];best=i;}

    printf("%d\n",best);

    cJSON_Delete(root); free(wtxt);
    return 0;
}
